package in.ac.rtu.medicare.web;
import in.ac.rtu.medicare.model.*; import jakarta.servlet.*; import jakarta.servlet.annotation.WebFilter; import jakarta.servlet.http.*; import java.io.IOException; import java.util.*;
@WebFilter(urlPatterns={"/app/*"}) public class AuthFilter implements Filter { public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException {HttpServletRequest r=(HttpServletRequest)req;HttpServletResponse p=(HttpServletResponse)res;HttpSession session=r.getSession(false);User u=session==null?null:(User)session.getAttribute("user");if(u==null){p.sendRedirect(r.getContextPath()+"/login");return;}String path=r.getRequestURI();if(path.contains("/admin")&&u.role()!=Role.ADMIN){p.sendError(403);return;}chain.doFilter(req,res);} }
